from __future__ import annotations

import json
import logging
from typing import Any

from fastapi import HTTPException

from mlflow.entities.assessment import Feedback
from mlflow.entities.gateway_guardrail import GuardrailAction, GuardrailStage
from mlflow.gateway.providers.utils import send_request
from mlflow.types.chat import ChatCompletionRequest

_logger = logging.getLogger(__name__)

# Path (relative to ``action_llm_url``) of the OpenAI-compatible chat completions
# endpoint exposed by the gateway. Sanitization requests are routed through it.
_CHAT_COMPLETIONS_PATH = "gateway/mlflow/v1/chat/completions"


class GuardrailViolation(Exception):
    """Exception raised when a guardrail blocks a request or response.

    The error message contains the guardrail name and the scorer's rationale so
    that it can be surfaced to the caller. When no specific rationale is
    available the message is simply ``"blocked"``.
    """

    def __init__(
        self,
        message: str | None = None,
        *,
        name: str | None = None,
        rationale: str | None = None,
    ):
        if message is None:
            if name is not None and rationale:
                message = f"Guardrail '{name}' blocked the content: {rationale}"
            else:
                message = "blocked"
        self.message = message
        super().__init__(message)


def _scalar_passing(value: Any) -> bool:
    """Interpret a raw scorer value as pass (True) or fail (False).

    ``True`` and a case-insensitive ``"yes"`` string are passing; ``False`` and
    any other string are failing. Any other type is unsupported.
    """
    # ``bool`` must be checked before ``str`` (and before any int handling)
    # because ``bool`` is a subclass of ``int``.
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.strip().lower() == "yes"
    raise TypeError(f"unexpected value type: {type(value).__name__}")


def _interpret_result(result: Any) -> tuple[bool, str | None]:
    """Reduce a scorer result to ``(passing, rationale)``.

    Accepts a :class:`Feedback`, a list of :class:`Feedback` (all must pass), or
    a raw ``bool``/``str`` scalar. Unsupported value types raise ``TypeError``.
    """
    if isinstance(result, Feedback):
        return _scalar_passing(result.value), result.rationale
    if isinstance(result, list):
        for item in result:
            if isinstance(item, Feedback):
                if not _scalar_passing(item.value):
                    return False, item.rationale
            elif not _scalar_passing(item):
                return False, None
        return True, None
    return _scalar_passing(result), None


class JudgeGuardrail:
    """Guardrail that uses a scorer to validate or sanitize gateway traffic."""

    def __init__(
        self,
        scorer: Any,
        stage: GuardrailStage,
        action: GuardrailAction,
        name: str,
        action_llm_url: str = None,
        action_endpoint_name: str = None,
    ):
        self.scorer = scorer
        self.stage = stage
        self.action = action
        self.name = name
        self.action_llm_url = action_llm_url
        self.action_endpoint_name = action_endpoint_name

    async def process_request(self, request: dict) -> dict:
        if self.stage != GuardrailStage.BEFORE:
            return request
        return await self._apply_action(request)

    async def process_response(self, request: dict, response: dict) -> dict:
        if self.stage != GuardrailStage.AFTER:
            return response
        return await self._apply_action(response)

    async def _apply_action(self, payload: dict) -> dict:
        result = self.scorer(payload)
        passing, rationale = _interpret_result(result)
        if passing:
            return payload

        if self.action == GuardrailAction.VALIDATION:
            raise GuardrailViolation(name=self.name, rationale=rationale)

        # SANITIZATION
        if self.action_llm_url is None:
            raise GuardrailViolation(
                f"Guardrail '{self.name}' requires action_llm_url to sanitize content, "
                "but none is configured."
            )
        return await self._sanitize(payload)

    async def _sanitize(self, payload: dict) -> dict:
        sanitization_payload = {
            "messages": [
                {
                    "role": "system",
                    "content": (
                        "You are a content sanitization assistant. Rewrite the provided "
                        "chat completion payload so that it no longer violates the content "
                        "policy, preserving the original intent as much as possible. Respond "
                        "only with the sanitized payload as JSON."
                    ),
                },
                {"role": "user", "content": json.dumps(payload)},
            ],
            "response_format": {
                "type": "json_schema",
                "json_schema": {
                    "name": "sanitized_payload",
                    "strict": False,
                    "schema": ChatCompletionRequest.model_json_schema(),
                },
            },
        }
        if self.action_endpoint_name:
            sanitization_payload["model"] = self.action_endpoint_name

        try:
            response = await send_request(
                headers={},
                base_url=self.action_llm_url,
                path=_CHAT_COMPLETIONS_PATH,
                payload=sanitization_payload,
            )
        except HTTPException as e:
            raise GuardrailViolation(f"Sanitization request failed: {e.detail}")

        content = response["choices"][0]["message"]["content"]
        try:
            return json.loads(content)
        except (json.JSONDecodeError, TypeError) as e:
            raise GuardrailViolation(
                f"Sanitization endpoint returned invalid JSON content: {e}"
            )

